CREATE TRIGGER asset_import_identity BEFORE UPDATE ON asset_imports WHEN NEW.id IS NOT OLD.id OR NEW.project_id IS NOT OLD.project_id OR NEW.owner_id IS NOT OLD.owner_id OR NEW.operation_id IS NOT OLD.operation_id OR NEW.request_hash IS NOT OLD.request_hash OR NEW.request_json IS NOT OLD.request_json OR NEW.object_key IS NOT OLD.object_key OR NEW.created_at IS NOT OLD.created_at OR (OLD.state='VERIFIED' AND (NEW.state IS NOT OLD.state OR NEW.inspection_json IS NOT OLD.inspection_json)) BEGIN SELECT RAISE(ABORT,'IMPORT_IMMUTABLE'); END;
